	}
	h := stdout.String()
	for _, frag := range []string{"evaluate", "config.json", "context.json", "disabled|rule|default", "eq", "in"} {
		if !strings.Contains(h, frag) {
			t.Errorf("help missing %q", frag)
		}
	}

	// 未知命令仍是退出码 2。
	stdout.Reset()
	stderr.Reset()
	if code := run([]string{"bogus"}, &stdout, &stderr); code != 2 {
		t.Fatalf("unknown command exit=%d want 2", code)
	}
}

// extraCLIConfig 与 validConfig 的开关定义相同，另在顶层、开关、规则、条件上
// 附带对象、数组、布尔、null 与语法合法但超出浮点范围的大数字（1e400、
// 1 后接 400 个 0 的整数）。这些附加信息不参与求值。
var extraCLIConfig = `{"meta":{"owner":"pay","big":1e400,"huge":` + "1" + strings.Repeat("0", 400) + `,"tags":["x",1e400],"ok":true,"nil":null},"flags":[
	{"key":"feature-a","enabled":true,"default":false,"note":"A","labels":["a"],"reviewed":true,"archived":null,"rules":[
		{"id":"r-pro","value":true,"comment":{"n":1e400},"conditions":[
			{"attribute":"plan","op":"eq","value":"pro","hint":"plan"},
			{"attribute":"region","op":"in","value":["cn","us"],"weight":1e400}]}]},
	{"key":"feature-b","enabled":false,"default":true,"rules":[],"meta":{"big":1e400}},
	{"key":"feature-c","enabled":true,"default":true,"rules":[]}]}`

func TestCLIEvaluateExtraFieldsDoNotChangeResult(t *testing.T) {
	// 附加信息不改变求值：带附加字段的配置与 validConfig 对同一开关键、同一
	// 上下文的输出逐字节一致；stdout 仍是单个结果对象，stderr 为空。
	cases := []struct {
		name string
		key  string
		ctx  string
	}{
		{"first matching rule", "feature-a", `{"plan":"pro","region":"cn"}`},
		{"default fallback", "feature-a", `{}`},
		{"disabled flag", "feature-b", `{"plan":"pro","region":"cn"}`},
		{"no rules default", "feature-c", `{}`},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			plain := newHarness(t, validConfig, tc.ctx)
			extras := newHarness(t, extraCLIConfig, tc.ctx)
			var plainOut, extraOut, extraErr bytes.Buffer
			if code := run(plain.evalArgs(tc.key), &plainOut, &bytes.Buffer{}); code != 0 {
				t.Fatalf("plain config: exit=%d", code)
			}
			if code := run(extras.evalArgs(tc.key), &extraOut, &extraErr); code != 0 {
				t.Fatalf("config with extra fields: exit=%d stderr=%s", code, extraErr.String())
			}
			if extraErr.Len() != 0 {
				t.Fatalf("stderr must be empty on success: %q", extraErr.String())
			}
			if extraOut.String() != plainOut.String() {
				t.Fatalf("extra fields changed output: %q != %q", extraOut.String(), plainOut.String())
			}
			var got map[string]any
			if err := json.Unmarshal(extraOut.Bytes(), &got); err != nil {
				t.Fatalf("stdout is not a single JSON object: %q (%v)", extraOut.String(), err)
			}
			if got["key"] != tc.key {
				t.Fatalf("unexpected payload: %v", got)
			}
		})
	}
}

func TestCLIEvaluateExtraFieldFailures(t *testing.T) {
	// 附加信息虽不参与求值，仍属于被完整检查的配置：其中的重复字段与无效
	// JSON 都要非零退出、stdout 为空，stderr 指出问题来自配置，且原因能区分
	// 重复字段与无效 JSON。
	hugeInt := "1" + strings.Repeat("0", 400)
	cases := []struct {
		name    string
		config  string
		key     string
		wantSub []string // stderr 必须包含的片段
		notSub  []string // stderr 不得包含的片段
	}{
		{
			"duplicate after exponent overflow in extra object",
			`{"flags":[{"key":"f","enabled":true,"default":false,"rules":[],
				"meta":{"n":1e400,"n":2}}]}`,
			"f",
			[]string{"config", "duplicate field", `config.flags[0].meta.n`},
			[]string{"invalid JSON"},
		},
		{
			"duplicate after 400-digit integer in extra object",
			`{"flags":[{"key":"f","enabled":true,"default":false,"rules":[],
				"meta":{"n":` + hugeInt + `,"n":2}}]}`,
			"f",
			[]string{"config", "duplicate field", `config.flags[0].meta.n`},
			[]string{"invalid JSON"},
		},
		{
			"duplicate in unselected flag extra field",
			`{"flags":[
				{"key":"good","enabled":true,"default":false,"rules":[]},
				{"key":"bad","enabled":true,"default":false,"rules":[],"meta":{"x":1,"x":2}}]}`,
			"good",
			[]string{"config", "duplicate field", `config.flags[1].meta.x`},
			nil,
		},
		{
			"duplicate in disabled flag extra field",
			`{"flags":[{"key":"off","enabled":false,"default":false,"rules":[],"meta":{"x":1,"x":2}}]}`,
			"off",
			[]string{"config", "duplicate field", `config.flags[0].meta.x`},
			nil,
		},
		{
			"malformed number in extra field",
			`{"flags":[{"key":"f","enabled":true,"default":false,"rules":[],
				"meta":{"n":1e+}}]}`,
			"f",
			[]string{"config: invalid JSON"},
			[]string{"duplicate field"},
		},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			h := newHarness(t, tc.config, `{}`)
			var stdout, stderr bytes.Buffer
			if code := run(h.evalArgs(tc.key), &stdout, &stderr); code == 0 {
				t.Fatalf("expected non-zero exit, stdout=%q", stdout.String())
			}
			if stdout.Len() != 0 {
				t.Fatalf("stdout must be empty on error, got %q", stdout.String())
			}
			msg := stderr.String()
			for _, want := range tc.wantSub {
				if !strings.Contains(msg, want) {
					t.Fatalf("stderr=%q, want substring %q", msg, want)
				}
			}
			for _, not := range tc.notSub {
				if strings.Contains(msg, not) {
					t.Fatalf("stderr=%q, must not contain %q", msg, not)
				}
			}
		})
	}
}

// --- 标识名称写法回归：直接字符与合法 \uXXXX 转义按解码后的文字识别 ------------

// evalSuccess 运行 evaluate 并要求成功：退出码 0、stderr 为空、stdout 恰好是
// 一行 JSON 对象。返回解码后的字段与 stdout 原文（供逐字节比较）。
func evalSuccess(t *testing.T, h *harness, key string) (map[string]any, string) {
	t.Helper()
	var stdout, stderr bytes.Buffer
	if code := run(h.evalArgs(key), &stdout, &stderr); code != 0 {
		t.Fatalf("key %q: exit=%d stderr=%q", key, code, stderr.String())
	}
	if stderr.Len() != 0 {
		t.Fatalf("key %q: stderr must be empty on success: %q", key, stderr.String())
	}
	out := stdout.String()
	if strings.Count(strings.TrimSpace(out), "\n") != 0 {
		t.Fatalf("key %q: stdout must contain exactly one JSON object line: %q", key, out)
	}
	var got map[string]any
	if err := json.Unmarshal(stdout.Bytes(), &got); err != nil {
		t.Fatalf("key %q: stdout is not a single JSON object: %q (%v)", key, out, err)
	}
	return got, out
}

// evalFailure 运行 evaluate 并要求失败：退出码非零、stdout 为空。返回 stderr 原文。
func evalFailure(t *testing.T, h *harness, key string) string {
	t.Helper()
	var stdout, stderr bytes.Buffer
	if code := run(h.evalArgs(key), &stdout, &stderr); code == 0 {
		t.Fatalf("key %q: expected non-zero exit, stdout=%q", key, stdout.String())
	}
	if stdout.Len() != 0 {
		t.Fatalf("key %q: stdout must be empty on error, got %q", key, stdout.String())
	}
	return stderr.String()
}

// escapeNameConfig 用给定的 key/id 写法（JSON 字符串内容，不含引号）拼出一份
// 合法配置：一个启用的开关，一条 eq 规则（plan=pro 命中，value=true），
// default=false。只有名称写法可变，业务内容固定。
func escapeNameConfig(keyJSON, idJSON string) string {
	return `{"flags":[{"key":"` + keyJSON + `","enabled":true,"default":false,"rules":[` +
		`{"id":"` + idJSON + `","value":true,"conditions":[` +
		`{"attribute":"plan","op":"eq","value":"pro"}]}]}]}`
}

// TestCLIEvaluateNameEscapeSpellingsEquivalent 验证同一个名字无论写成直接
// UTF-8 字符、合法 \uXXXX 转义还是两者混合，读入后都按解码文字识别：用解码后
// 的开关键请求时找到同一个开关，同一上下文命中同一条规则，布尔结果与原因一致，
// 结果中的 key 与 ruleId 还原为同一名称。名称同时含普通文字（é，BMP 内单个
// \u00E9）与必须完整代理项配对才能表示的字符（🚀 = \uD83D\uDE80）。
func TestCLIEvaluateNameEscapeSpellingsEquivalent(t *testing.T) {
	const (
		decodedKey = "café🚀"
		decodedID  = "r-é🚀"
	)
	keySpellings := []struct{ name, json string }{
		{"direct", `café🚀`},
		{"escaped", `caf\u00E9\uD83D\uDE80`},
		{"mixed", `caf\u00E9🚀`},
	}
	idSpellings := []struct{ name, json string }{
		{"direct", `r-é🚀`},
		{"escaped", `r-\u00E9\uD83D\uDE80`},
		{"mixed", `r-é\uD83D\uDE80`},
	}
	var reference string // 直接写法的 stdout 原文，其余写法必须逐字节一致
	for _, ks := range keySpellings {
		for _, is := range idSpellings {
			t.Run("key="+ks.name+"/id="+is.name, func(t *testing.T) {
				h := newHarness(t, escapeNameConfig(ks.json, is.json), `{"plan":"pro"}`)
				got, raw := evalSuccess(t, h, decodedKey)
				if got["key"] != decodedKey || got["value"] != true ||
					got["reason"] != "rule" || got["ruleId"] != decodedID {
					t.Fatalf("unexpected payload: %v", got)
				}
				// 结果中的名称是解码后的文字本身，不是转义写法。
				if !strings.Contains(raw, decodedKey) || !strings.Contains(raw, decodedID) {
					t.Fatalf("stdout must carry the decoded names: %q", raw)
				}
				if ks.name == "direct" && is.name == "direct" {
					reference = raw
				} else if raw != reference {
					t.Fatalf("spelling changed output:\n%s\n!= reference:\n%s", raw, reference)
				}
			})
		}
	}
}

// TestCLIEvaluateDuplicateFlagKeyAcrossSpellings 验证开关键冲突按解码后的文字
// 判断：两个开关分别用直接写法与转义写法声明同一个 key 时整份配置被拒绝，
// 错误指出后出现的位置与第一次出现的位置，且不会误报成同一对象的字段重复。
func TestCLIEvaluateDuplicateFlagKeyAcrossSpellings(t *testing.T) {
	flag := func(keyJSON string) string {
		return `{"key":"` + keyJSON + `","enabled":true,"default":false,"rules":[]}`
	}
	cases := []struct {
		name    string
		config  string
		wantSub []string
	}{
		{
			"direct then escaped",
			`{"flags":[` + flag(`café`) + `,` + flag(`caf\u00E9`) + `]}`,
			[]string{`config.flags[1].key`, `duplicate flag key`, `"café"`, `first at flags[0]`},
		},
		{
			"escaped then direct",
			`{"flags":[` + flag(`caf\u00E9`) + `,` + flag(`café`) + `]}`,
			[]string{`config.flags[1].key`, `duplicate flag key`, `"café"`, `first at flags[0]`},
		},
		{
			"surrogate pair direct then escaped",
			`{"flags":[` + flag(`a🚀`) + `,` + flag(`a\uD83D\uDE80`) + `]}`,
			[]string{`config.flags[1].key`, `duplicate flag key`, `"a🚀"`, `first at flags[0]`},
		},
		{
			"mixed vs mixed",
			`{"flags":[` + flag(`caf\u00E9🚀`) + `,` + flag(`café\uD83D\uDE80`) + `]}`,
			[]string{`config.flags[1].key`, `duplicate flag key`, `"café🚀"`, `first at flags[0]`},
		},
		{
			"later occurrence and first occurrence positions",
			`{"flags":[` + flag(`caf\u00E9`) + `,` + flag(`other`) + `,` + flag(`café`) + `]}`,
			[]string{`config.flags[2].key`, `duplicate flag key`, `first at flags[0]`},
		},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			h := newHarness(t, tc.config, `{}`)
			msg := evalFailure(t, h, "café🚀")
			for _, want := range tc.wantSub {
				if !strings.Contains(msg, want) {
					t.Fatalf("stderr=%q, want substring %q", msg, want)
				}
			}
			if strings.Contains(msg, "duplicate field") {
				t.Fatalf("key conflict must not be misreported as a duplicate field: %q", msg)
			}
		})
	}
}

// TestCLIEvaluateDuplicateRuleIDAcrossSpellings 验证同一开关里的两条规则用不同
// 写法声明同一个 id 时整份配置被拒绝，错误与开关键重复、字段重复明确区分，
// 并指出后出现与第一次出现的位置。
func TestCLIEvaluateDuplicateRuleIDAcrossSpellings(t *testing.T) {
	rule := func(idJSON string) string {
		return `{"id":"` + idJSON + `","value":true,"conditions":[` +
			`{"attribute":"plan","op":"eq","value":"pro"}]}`
	}
	configWith := func(first, second string) string {
		return `{"flags":[{"key":"f","enabled":true,"default":false,"rules":[` +
			rule(first) + `,` + rule(second) + `]}]}`
	}
	cases := []struct {
		name   string
		config string
	}{
		{"direct then escaped", configWith(`r-🚀`, `r-\uD83D\uDE80`)},
		{"escaped then direct", configWith(`r-\uD83D\uDE80`, `r-🚀`)},
		{"mixed vs mixed", configWith(`r-é\uD83D\uDE80`, `r-\u00E9🚀`)},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			h := newHarness(t, tc.config, `{"plan":"pro"}`)
			msg := evalFailure(t, h, "f")
			for _, want := range []string{
				`config.flags[0].rules[1].id`, `duplicate rule id`, `first at rules[0]`,
			} {
				if !strings.Contains(msg, want) {
					t.Fatalf("stderr=%q, want substring %q", msg, want)
				}
			}
			for _, not := range []string{"duplicate field", "duplicate flag key"} {
				if strings.Contains(msg, not) {
					t.Fatalf("rule id conflict misreported: stderr=%q must not contain %q", msg, not)
				}
			}
		})
	}
}

// TestCLIEvaluateNameConflictAnywhereRejectsWholeConfig 验证名称冲突无论位于
// 未选中的开关还是已关闭的开关，整份配置都被拒绝：请求另一个完全合法的开关
// 同样非零退出、stdout 为空。
func TestCLIEvaluateNameConflictAnywhereRejectsWholeConfig(t *testing.T) {
	good := `{"key":"good","enabled":true,"default":true,"rules":[]}`
	dupKeyFlags := func(enabled string) string {
		return `{"key":"café","enabled":` + enabled + `,"default":false,"rules":[]},` +
			`{"key":"caf\u00E9","enabled":` + enabled + `,"default":false,"rules":[]}`
	}
	dupRuleFlag := func(enabled string) string {
		return `{"key":"dup","enabled":` + enabled + `,"default":false,"rules":[` +
			`{"id":"r-🚀","value":true,"conditions":[{"attribute":"plan","op":"eq","value":"pro"}]},` +
			`{"id":"r-\uD83D\uDE80","value":false,"conditions":[{"attribute":"plan","op":"eq","value":"pro"}]}]}`
	}
	cases := []struct {
		name    string
		config  string
		wantSub string
	}{
		{"duplicate key in unselected flags", `{"flags":[` + good + `,` + dupKeyFlags("true") + `]}`, "duplicate flag key"},
		{"duplicate key in disabled flags", `{"flags":[` + good + `,` + dupKeyFlags("false") + `]}`, "duplicate flag key"},
		{"duplicate rule id in unselected flag", `{"flags":[` + good + `,` + dupRuleFlag("true") + `]}`, "duplicate rule id"},
		{"duplicate rule id in disabled flag", `{"flags":[` + good + `,` + dupRuleFlag("false") + `]}`, "duplicate rule id"},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			h := newHarness(t, tc.config, `{"plan":"pro"}`)
			if msg := evalFailure(t, h, "good"); !strings.Contains(msg, tc.wantSub) {
				t.Fatalf("stderr=%q, want substring %q", msg, tc.wantSub)
			}
		})
	}
}

// TestCLIEvaluateSameRuleIDAcrossFlagsIsLegal 验证不同开关各自使用解码后相同的
// 规则编号是合法的（唯一性以开关为界），求值结果中的编号属于实际选中的开关。
func TestCLIEvaluateSameRuleIDAcrossFlagsIsLegal(t *testing.T) {
	config := `{"flags":[
		{"key":"f1","enabled":true,"default":false,"rules":[
			{"id":"r-é🚀","value":true,"conditions":[{"attribute":"plan","op":"eq","value":"pro"}]}]},
		{"key":"f2","enabled":true,"default":true,"rules":[
			{"id":"r-\u00E9\uD83D\uDE80","value":false,"conditions":[{"attribute":"plan","op":"eq","value":"pro"}]}]}]}`
	h := newHarness(t, config, `{"plan":"pro"}`)

	got, _ := evalSuccess(t, h, "f1")
	if got["key"] != "f1" || got["value"] != true || got["reason"] != "rule" || got["ruleId"] != "r-é🚀" {
		t.Fatalf("f1: unexpected payload: %v", got)
	}
	got, _ = evalSuccess(t, h, "f2")
	if got["key"] != "f2" || got["value"] != false || got["reason"] != "rule" || got["ruleId"] != "r-é🚀" {
		t.Fatalf("f2: unexpected payload: %v", got)
	}
}

// TestCLIEvaluateSimilarNamesStayDistinct 验证名称的精确区分：大小写不同、前后
// 空白不同、外观相似但字符序列不同的名字（é 预组合 vs e+组合符、西里尔 а vs
// 拉丁 a）既不合并也不互认重复；请求一个仅相似、实际不存在的开关键时报告
// 未找到且 stdout 为空，而不是选择近似名称。
func TestCLIEvaluateSimilarNamesStayDistinct(t *testing.T) {
	// 每个合法 key 用不同的 default 值标记，求值结果可区分究竟选中了谁。
	// 注意 café（预组合 é，U+00E9）与 cafe\u0301（e + 组合符 U+0301）、
	// p\u0430y（西里尔 а，U+0430）与拉丁 pay 都是不同的名字。
	config := `{"flags":[
		{"key":"feature-a","enabled":true,"default":false,"rules":[]},
		{"key":"Feature-A","enabled":true,"default":true,"rules":[]},
		{"key":" feature-a","enabled":true,"default":true,"rules":[]},
		{"key":"feature-a ","enabled":true,"default":true,"rules":[]},
		{"key":"café","enabled":true,"default":false,"rules":[]},
		{"key":"cafe\u0301","enabled":true,"default":true,"rules":[]},
		{"key":"p\u0430y","enabled":true,"default":false,"rules":[]}]}`
	h := newHarness(t, config, `{}`)

	// 相似名字共存于同一份配置而不被误判为重复，且各自按精确名称求值。
	existing := []struct {
		key   string
		value bool
	}{
		{"feature-a", false},
		{"Feature-A", true},
		{" feature-a", true},
		{"feature-a ", true},
		{"café", false},
		{"cafe\u0301", true}, // e + 组合符 U+0301，与预组合的 "café" 不是同一个名字
		{"p\u0430y", false},  // 西里尔 а（U+0430）
	}
	for _, tc := range existing {
		got, _ := evalSuccess(t, h, tc.key)
		if got["key"] != tc.key || got["value"] != tc.value || got["reason"] != "default" {
			t.Fatalf("key %q: unexpected payload: %v", tc.key, got)
		}
	}

	// 仅大小写、空白或字符序列相似、实际不存在的 key 必须报告未找到。
	missing := []string{
		"feature-A",
		"FEATURE-A",
		"feature-a  ", // 两个尾随空格
		"  feature-a", // 两个前导空格
		"pay",         // 纯拉丁字母，配置里只有含西里尔 а 的 "p\u0430y"
		"cafe",        // 无重音符
		"café ",       // 尾随空格
	}
	for _, key := range missing {
		msg := evalFailure(t, h, key)
		if !strings.Contains(msg, "not found") {
			t.Fatalf("key %q: stderr=%q, want not found", key, msg)
		}
	}
}

// TestCLIEvaluateBackslashTextIsNotReDecoded 验证带有反斜杠、看起来像 Unicode
// 转义的普通文本不会被再次解码：JSON 里的 "\\u00E9" 解码为普通文本 u00E9，
// 它与真正的 "café" 是两个不同的合法名字，互不冲突、互不选中。
func TestCLIEvaluateBackslashTextIsNotReDecoded(t *testing.T) {
	// 第一个开关的 key/id 都是带反斜杠的普通文本；若被再次解码，两个开关的
	// key 都会变成 "café" 而被判重复——配置合法本身即证明没有二次解码。
	config := `{"flags":[
		{"key":"caf\\u00E9","enabled":true,"default":false,"rules":[
			{"id":"r-\\uD83D\\uDE80","value":true,"conditions":[
				{"attribute":"plan","op":"eq","value":"pro"}]}]},
		{"key":"café","enabled":true,"default":true,"rules":[]}]}`
	h := newHarness(t, config, `{"plan":"pro"}`)

	// 解码后的 "café" 选中第二个开关，而不是反斜杠文本那一个。
	got, _ := evalSuccess(t, h, "café")
	if got["key"] != "café" || got["value"] != true || got["reason"] != "default" || got["ruleId"] != nil {
		t.Fatalf("decoded name must select the real café flag: %v", got)
	}

	// 反斜杠文本按原样是一个独立 key：结果中的名称保持原文，不变成转义解码
	// 后的字符。
	literalKey := `caf\u00E9`
	literalID := `r-\uD83D\uDE80`
	got, _ = evalSuccess(t, h, literalKey)
	if got["key"] != literalKey || got["value"] != true ||
		got["reason"] != "rule" || got["ruleId"] != literalID {
		t.Fatalf("backslash text must stay a literal name: %v", got)
	}
}

// TestCLIEvaluateNameErrorPrecedencePreserved 沿用现有错误优先级：文档级检查
// （非法 Unicode 转义、同一对象重复字段）先于业务唯一性（重复开关键）报告。
func TestCLIEvaluateNameErrorPrecedencePreserved(t *testing.T) {
	cases := []struct {
		name    string
		config  string
		wantSub string
		notSub  string
	}{
		{
			// flags[1] 同一对象内重复声明 key（第二次写法解码后与 flags[0]
			// 冲突）：报字段重复，而不是开关键重复。
			"duplicate field beats duplicate flag key",
			`{"flags":[
				{"key":"café","enabled":true,"default":false,"rules":[]},
				{"key":"other","key":"caf\u00E9","enabled":true,"default":false,"rules":[]}]}`,
			`config.flags[1].key: duplicate field "key"`,
			"duplicate flag key",
		},
		{
			// flags[1] 的 key 与 flags[0] 解码后冲突，同时其条件值含孤立
			// 代理项转义：报非法转义，而不是开关键重复。
			"invalid escape beats duplicate flag key",
			`{"flags":[
				{"key":"café","enabled":true,"default":false,"rules":[]},
				{"key":"caf\u00E9","enabled":true,"default":false,"rules":[
					{"id":"r","value":true,"conditions":[{"attribute":"a","op":"eq","value":"\uD800"}]}]}]}`,
			"invalid Unicode escape",
			"duplicate flag key",
		},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			h := newHarness(t, tc.config, `{}`)
			msg := evalFailure(t, h, "café")
			if !strings.Contains(msg, tc.wantSub) {
				t.Fatalf("stderr=%q, want substring %q", msg, tc.wantSub)
			}
			if strings.Contains(msg, tc.notSub) {
				t.Fatalf("stderr=%q, must not contain %q", msg, tc.notSub)
			}
		})
	}
}

// --- evaluate 对 in 条件精确成员判断的端到端回归保障 ---------------------------
//
// 下列常量用 Go 原始字符串拼接出 JSON 转义文本（与本文件既有写法一致），确保
// “转义写法”和“直接字符”在源码层面就是两个不同的输入。
const (
	// cliEscEA 是 U+00E9 的 JSON 转义写法；cliEscCB 是 e 加组合附加符号 U+0301
	// 的转义写法（与预组合字符不同）；cliEscGR 是 U+1F600 的一对代理项转义；
	// cliEscTier 是属性名 tier 四个字母各自转义后的写法。
	cliEscEA   = (`\u` + `00E9`)
	cliEscCB   = (`e\u` + `0301`)
	cliEscGR   = (`\u` + `D83D`) + (`\u` + `DE00`)
	cliEscTier = (`\u` + `0074`) + (`\u` + `0069`) + (`\u` + `0065`) + (`\u` + `0072`)
	// cliLitEA 是 JSON 里“已转义的反斜杠后接 u00E9”的普通文本（两个反斜杠
	// 后接 u00E9），解码后只是六个字面字符，不再是 Unicode 转义。
	cliLitEA = (`\` + `\` + `u00E9`)
)

// cliInListConfig 拼出只有一个启用开关、一条 in 规则（id=r1、value=true、
// default=false）的配置；listJSON 是完整的候选值数组文本。
func cliInListConfig(listJSON string) string {
	return `{"flags":[{"key":"f","enabled":true,"default":false,"rules":[` +
		`{"id":"r1","value":true,"conditions":[` +
		`{"attribute":"tier","op":"in","value":` + listJSON + `}]}]}]}`
}

// TestCLIEvaluateInDecodedSpellingEquivalence 端到端验证：同一属性名、列表
// 候选值或上下文值，无论用直接字符还是合法 Unicode 转义（含代理项对）书写，
// evaluate 都输出逐字节一致的单个 JSON 对象（key、value、reason、ruleId
// 完全一致）；配置与上下文可分别使用不同写法。
func TestCLIEvaluateInDecodedSpellingEquivalence(t *testing.T) {
	configs := []struct {
		name string
		raw  string
	}{
		{"direct", cliInListConfig(`["é","😀","other"]`)},
		{"escaped", cliInListConfig(`["` + cliEscEA + `","` + cliEscGR + `","other"]`)},
		{"mixed", cliInListConfig(`["é","` + cliEscGR + `","other"]`)},
	}
	contexts := []struct {
		name string
		raw  string
	}{
		{"e-acute direct", `{"tier":"é"}`},
		{"e-acute escaped", `{"tier":"` + cliEscEA + `"}`},
		{"emoji direct", `{"tier":"😀"}`},
		{"emoji surrogate pair", `{"tier":"` + cliEscGR + `"}`},
		{"plain ascii", `{"tier":"other"}`},
	}
	var reference string
	for ci, cfg := range configs {
		for _, cx := range contexts {
			t.Run(cfg.name+"/"+cx.name, func(t *testing.T) {
				h := newHarness(t, cfg.raw, cx.raw)
				got, raw := evalSuccess(t, h, "f")
				if got["key"] != "f" || got["value"] != true ||
					got["reason"] != "rule" || got["ruleId"] != "r1" {
					t.Fatalf("unexpected payload: %v", got)
				}
				if ci == 0 && cx.name == "e-acute direct" {
					reference = raw
				} else if raw != reference {
					t.Fatalf("spelling changed output:\n%s\n!= reference:\n%s", raw, reference)
				}
			})
		}
	}
}

// TestCLIEvaluateInLookalikesStayDistinct 端到端验证外形相近但解码后不相等的
// 值不属于 in 列表：大小写、首尾空白、预组合字符与 e+U+0301 序列都按原样
// 区分；已转义的反斜杠后即使跟 u 和十六进制数字也只是普通文本，不再解码。
func TestCLIEvaluateInLookalikesStayDistinct(t *testing.T) {
	config := cliInListConfig(`["é","AbC"]`)
	misses := []struct {
		name string
		ctx  string
	}{
		{"uppercase", `{"tier":"É"}`},
		{"lowercase", `{"tier":"abc"}`},
		{"leading space", `{"tier":" é"}`},
		{"trailing space", `{"tier":"é "}`},
		{"combining sequence", `{"tier":"` + cliEscCB + `"}`},
	}
	for _, tc := range misses {
		t.Run(tc.name, func(t *testing.T) {
			h := newHarness(t, config, tc.ctx)
			got, _ := evalSuccess(t, h, "f")
			// 未命中任何规则：采用 default=false，ruleId 为 null。
			if got["reason"] != "default" || got["value"] != false || got["ruleId"] != nil {
				t.Fatalf("lookalike must not belong to the list: %v", got)
			}
		})
	}

	// 列表候选是反斜杠普通文本：相同字面文本命中；解码出的字符（直接写出或
	// 用合法 Unicode 转义）与该字面文本不同，不命中。
	literalConfig := `{"flags":[{"key":"g","enabled":true,"default":false,"rules":[
		{"id":"r1","value":true,"conditions":[
			{"attribute":"tier","op":"in","value":["` + cliLitEA + `"]}]}]}]}`
	h := newHarness(t, literalConfig, `{"tier":"`+cliLitEA+`"}`)
	if got, _ := evalSuccess(t, h, "g"); got["reason"] != "rule" {
		t.Fatalf("backslash literal text must equal the same literal text: %v", got)
	}
	for _, tc := range []struct {
		name string
		ctx  string
	}{
		{"decoded direct", `{"tier":"é"}`},
		{"decoded via escape", `{"tier":"` + cliEscEA + `"}`},
	} {
		t.Run(tc.name, func(t *testing.T) {
			h := newHarness(t, literalConfig, tc.ctx)
			got, _ := evalSuccess(t, h, "g")
			if got["reason"] != "default" || got["ruleId"] != nil {
				t.Fatalf("decoded value must not match backslash literal text: %v", got)
			}
		})
	}
}

// TestCLIEvaluateInExactAttributeLookup 端到端验证 in 条件的属性名精确查找：
// 转义写法与直接字符读同一属性；外形接近的另一个属性即使持有列表内的值也不
// 参与判断。
func TestCLIEvaluateInExactAttributeLookup(t *testing.T) {
	config := cliInListConfig(`["a"]`)
	for i, ctx := range []string{
		`{"tier":"a"}`,
		`{"` + cliEscTier + `":"a"}`, // tier 四个字母分别用 Unicode 转义书写
	} {
		h := newHarness(t, config, ctx)
		got, _ := evalSuccess(t, h, "f")
		if got["reason"] != "rule" || got["ruleId"] != "r1" {
			t.Fatalf("hit case %d: unexpected payload: %v", i, got)
		}
	}
	for _, tc := range []struct {
		name string
		ctx  string
	}{
		{"capitalized attr holds member", `{"Tier":"a"}`},
		{"exact attr holds non-member", `{"tier":"z","Tier":"a"}`},
		{"spaced attr holds member", `{" tier":"a"}`},
	} {
		t.Run(tc.name, func(t *testing.T) {
			h := newHarness(t, config, tc.ctx)
			got, _ := evalSuccess(t, h, "f")
			if got["reason"] != "default" || got["ruleId"] != nil {
				t.Fatalf("lookalike attribute must not satisfy an in condition: %v", got)
			}
		})
	}

	// 属性名区分预组合字符与 e+U+0301 序列；转义写法与直接字符同名。
	accentConfig := `{"flags":[{"key":"f","enabled":true,"default":false,"rules":[
		{"id":"r1","value":true,"conditions":[
			{"attribute":"café","op":"in","value":["a"]}]}]}]}`
	h := newHarness(t, accentConfig, `{"café":"a"}`)
	if got, _ := evalSuccess(t, h, "f"); got["reason"] != "rule" {
		t.Fatalf("precomposed attribute must be found: %v", got)
	}
	h = newHarness(t, accentConfig, `{"caf`+cliEscCB+`":"a"}`)
	if got, _ := evalSuccess(t, h, "f"); got["reason"] != "default" {
		t.Fatalf("combining-sequence attribute must not satisfy a precomposed lookup: %v", got)
	}
}

// TestCLIEvaluateInRuleDecisionAndEmptyMember 端到端验证 in 条件与规则定案
// 顺序的配合，以及空字符串成员与属性缺失的区分。
func TestCLIEvaluateInRuleDecisionAndEmptyMember(t *testing.T) {
	// 前一条 in 规则返回 false，后一条 eq 规则返回 true，二者可同时成立。
	priorityConfig := `{"flags":[{"key":"f","enabled":true,"default":true,"rules":[
		{"id":"r-deny","value":false,"conditions":[
			{"attribute":"plan","op":"eq","value":"pro"},
			{"attribute":"tier","op":"in","value":["é","a"]}]},
		{"id":"r-allow","value":true,"conditions":[
			{"attribute":"region","op":"eq","value":"cn"}]}]}]}`
	for _, tc := range []struct {
		name   string
		ctx    string
		ruleID string
		value  bool
	}{
		{"exact member direct", `{"plan":"pro","tier":"é","region":"cn"}`, "r-deny", false},
		{"exact member escaped", `{"plan":"pro","tier":"` + cliEscEA + `","region":"cn"}`, "r-deny", false},
		{"lookalike falls through", `{"plan":"pro","tier":"` + cliEscCB + `","region":"cn"}`, "r-allow", true},
		{"uppercase falls through", `{"plan":"pro","tier":"A","region":"cn"}`, "r-allow", true},
		{"missing attr falls through", `{"plan":"pro","region":"cn"}`, "r-allow", true},
		{"no rule holds uses default", `{"plan":"free","region":"eu"}`, "", true},
	} {
		t.Run(tc.name, func(t *testing.T) {
			h := newHarness(t, priorityConfig, tc.ctx)
			got, _ := evalSuccess(t, h, "f")
			if tc.ruleID == "" {
				if got["reason"] != "default" || got["ruleId"] != nil || got["value"] != tc.value {
					t.Fatalf("unexpected payload: %v", got)
				}
			} else if got["reason"] != "rule" || got["ruleId"] != tc.ruleID || got["value"] != tc.value {
				t.Fatalf("unexpected payload: %v", got)
			}
		})
	}

	// 空字符串是合法列表成员：显式给出空串命中；空白与属性缺失都不成立。
	emptyConfig := `{"flags":[{"key":"g","enabled":true,"default":false,"rules":[
		{"id":"r1","value":true,"conditions":[
			{"attribute":"note","op":"in","value":[""]}]}]}]}`
	h := newHarness(t, emptyConfig, `{"note":""}`)
	if got, _ := evalSuccess(t, h, "g"); got["reason"] != "rule" || got["ruleId"] != "r1" {
		t.Fatalf("explicit empty string must hit the in-list: %v", got)
	}
	h = newHarness(t, emptyConfig, `{"note":" "}`)
	if got, _ := evalSuccess(t, h, "g"); got["reason"] != "default" {
		t.Fatalf("whitespace is not the empty-string member: %v", got)
	}
	h = newHarness(t, emptyConfig, `{}`)
	if got, _ := evalSuccess(t, h, "g"); got["reason"] != "default" || got["ruleId"] != nil {
		t.Fatalf("missing attribute must not satisfy empty-string membership: %v", got)
	}
}

// TestCLIEvaluateInvalidInListsRejected 端到端验证空列表与含非字符串项的列表
// 仍是配置错误：错误指出相应位置；通过 evaluate 使用这些无效配置时非零退出、
// stdout 为空。未被选中与已关闭开关中的同类错误同样让整份配置失败。
func TestCLIEvaluateInvalidInListsRejected(t *testing.T) {
	const cond0 = `config.flags[0].rules[0].conditions[0].value`
	cases := []struct {
		name    string
		config  string
		key     string
		wantSub []string
	}{
		{
			"empty in-list",
			`{"flags":[{"key":"f","enabled":true,"default":false,"rules":[
				{"id":"r","value":true,"conditions":[
					{"attribute":"a","op":"in","value":[]}]}]}]}`,
			"f",
			[]string{cond0, "in-list must contain at least one item"},
		},
		{
			"non-string first item",
			`{"flags":[{"key":"f","enabled":true,"default":false,"rules":[
				{"id":"r","value":true,"conditions":[
					{"attribute":"a","op":"in","value":[1]}]}]}]}`,
			"f",
			[]string{cond0 + `[0]`, "must be a string"},
		},
		{
			"non-string later item keeps its index",
			`{"flags":[{"key":"f","enabled":true,"default":false,"rules":[
				{"id":"r","value":true,"conditions":[
					{"attribute":"a","op":"in","value":["x",true,null]}]}]}]}`,
			"f",
			[]string{cond0 + `[1]`, "must be a string"},
		},
		{
			"nested array item",
			`{"flags":[{"key":"f","enabled":true,"default":false,"rules":[
				{"id":"r","value":true,"conditions":[
					{"attribute":"a","op":"in","value":["x",["y"]]}]}]}]}`,
			"f",
			[]string{cond0 + `[1]`, "must be a string"},
		},
		{
			"object item",
			`{"flags":[{"key":"f","enabled":true,"default":false,"rules":[
				{"id":"r","value":true,"conditions":[
					{"attribute":"a","op":"in","value":[{"v":"x"}]}]}]}]}`,
			"f",
			[]string{cond0 + `[0]`, "must be a string"},
		},
		{
			"invalid list in an unselected flag still fails whole config",
			`{"flags":[
				{"key":"good","enabled":true,"default":true,"rules":[]},
				{"key":"bad","enabled":true,"default":false,"rules":[
					{"id":"r","value":true,"conditions":[
						{"attribute":"a","op":"in","value":["x",2]}]}]}]}`,
			"good",
			[]string{`config.flags[1].rules[0].conditions[0].value[1]`, "must be a string"},
		},
		{
			"invalid list in a disabled flag still fails whole config",
			`{"flags":[{"key":"off","enabled":false,"default":true,"rules":[
				{"id":"r","value":true,"conditions":[
					{"attribute":"a","op":"in","value":[]}]}]}]}`,
			"off",
			[]string{`config.flags[0].rules[0].conditions[0].value`, "in-list must contain at least one item"},
		},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			h := newHarness(t, tc.config, `{}`)
			msg := evalFailure(t, h, tc.key)
			for _, want := range tc.wantSub {
				if !strings.Contains(msg, want) {
					t.Fatalf("stderr=%q, want substring %q", msg, want)
				}
			}
		})
	}
}

// --- 可选 --explain 模式 ------------------------------------------------------

// explainCLIConfig 用于解释模式的端到端测试：r-block 在前返回 false（eq+in），
// r-pro 在后返回 true（eq）；另含一个已关闭的开关 off 与无规则开关 plain。
const explainCLIConfig = `{"flags":[
	{"key":"f","enabled":true,"default":true,"rules":[
		{"id":"r-block","value":false,"conditions":[
			{"attribute":"region","op":"eq","value":"cn"},
			{"attribute":"platform","op":"in","value":["ios","android"]}]},
		{"id":"r-pro","value":true,"conditions":[
			{"attribute":"plan","op":"eq","value":"pro"}]}]},
	{"key":"off","enabled":false,"default":true,"rules":[
		{"id":"r-only","value":true,"conditions":[
			{"attribute":"plan","op":"eq","value":"pro"}]}]},
	{"key":"plain","enabled":true,"default":true,"rules":[]}]}`

// evalExplainArgs 与 evalArgs 相同但末尾带 --explain。
func (h *harness) evalExplainArgs(key string) []string {
	return []string{"evaluate", h.configPath, key, h.contextPath, "--explain"}
}

// explainSuccess 运行带 --explain 的 evaluate 并把 stdout 解码为单个对象。
func explainSuccess(t *testing.T, h *harness, key string) map[string]any {
	t.Helper()
	var stdout, stderr bytes.Buffer
	if code := run(h.evalExplainArgs(key), &stdout, &stderr); code != 0 {
		t.Fatalf("exit=%d stderr=%s", code, stderr.String())
	}
	if stderr.Len() != 0 {
		t.Fatalf("stderr must be empty on success: %q", stderr.String())
	}
	out := stdout.String()
	if strings.Count(strings.TrimSpace(out), "\n") != 0 {
		t.Fatalf("stdout must contain exactly one JSON object line: %q", out)
	}
	var got map[string]any
	if err := json.Unmarshal(stdout.Bytes(), &got); err != nil {
		t.Fatalf("stdout is not a single JSON object: %q (%v)", out, err)
	}
	return got
}

// rulesOf 从解释对象中按顺序取出每条规则的 (id, match)。
func rulesOf(t *testing.T, got map[string]any) []map[string]any {
	t.Helper()
	exp, ok := got["explanation"].(map[string]any)
	if !ok {
		t.Fatalf("missing explanation object: %v", got)
	}
	rules, ok := exp["rules"].([]any)
	if !ok {
		t.Fatalf("explanation.rules must be an array: %v", exp)
	}
	res := make([]map[string]any, 0, len(rules))
	for _, r0 := range rules {
		res = append(res, r0.(map[string]any))
	}
	return res
}

func TestCLIEvaluateExplainRuleHitAndStop(t *testing.T) {
	h := newHarness(t, explainCLIConfig, `{"region":"cn","platform":"ios","plan":"pro"}`)
	got := explainSuccess(t, h, "f")
	// 前四个字段与普通模式一致。
	if got["key"] != "f" || got["value"] != false || got["reason"] != "rule" || got["ruleId"] != "r-block" {
		t.Fatalf("unexpected payload: %v", got)
	}
	rules := rulesOf(t, got)
	// 第一条全部条件成立的规则（返回 false）即定案并停止：只有 r-block。
	if len(rules) != 1 || rules[0]["ruleId"] != "r-block" || rules[0]["match"] != true {
		t.Fatalf("must list only the first all-match rule, got %v", rules)
	}
	conds := rules[0]["conditions"].([]any)
	if len(conds) != 2 {
		t.Fatalf("winning rule must show all its conditions: %v", conds)
	}
}

func TestCLIEvaluateExplainMissThenHit(t *testing.T) {
	h := newHarness(t, explainCLIConfig, `{"region":"us","platform":"web","plan":"pro"}`)
	got := explainSuccess(t, h, "f")
	if got["key"] != "f" || got["value"] != true || got["reason"] != "rule" || got["ruleId"] != "r-pro" {
		t.Fatalf("unexpected payload: %v", got)
	}
	rules := rulesOf(t, got)
	if len(rules) != 2 {
		t.Fatalf("missed earlier rule must be kept, deciding rule included: %v", rules)
	}
	if rules[0]["ruleId"] != "r-block" || rules[0]["match"] != false {
		t.Fatalf("first rule shown as miss: %v", rules[0])
	}
	if rules[1]["ruleId"] != "r-pro" || rules[1]["match"] != true {
		t.Fatalf("second rule shown as hit: %v", rules[1])
	}
}

func TestCLIEvaluateExplainConditionDetail(t *testing.T) {
	// 上下文缺失 region（与显式空字符串不同）、platform 值不在候选列表中。
	h := newHarness(t, explainCLIConfig, `{"platform":"","plan":"pro"}`)
	got := explainSuccess(t, h, "f")
	rules := rulesOf(t, got)
	conds := rules[0]["conditions"].([]any)

	region := conds[0].(map[string]any)
	if region["attribute"] != "region" || region["op"] != "eq" ||
		region["missing"] != true || region["actualValue"] != nil || region["match"] != false {
		t.Fatalf("missing region condition: %v", region)
	}
	platform := conds[1].(map[string]any)
	// 显式给出的空字符串是真实值，不能标记为缺失；但不在 ["ios","android"]。
	if platform["missing"] != false || platform["actualValue"] != "" || platform["match"] != false {
		t.Fatalf("empty-string platform must be present and out of list: %v", platform)
	}
	list := platform["compareValue"].([]any)
	if len(list) != 2 || list[0] != "ios" || list[1] != "android" {
		t.Fatalf("in compareValue wrong: %v", list)
	}

	// r-pro 的 plan 条件成立，体现“值不相等 vs 属性缺失 vs 不在列表”的区分。
	rpro := rules[1]["conditions"].([]any)[0].(map[string]any)
	if rpro["attribute"] != "plan" || rpro["compareValue"] != "pro" ||
		rpro["actualValue"] != "pro" || rpro["missing"] != false || rpro["match"] != true {
		t.Fatalf("plan condition: %v", rpro)
	}
}

func TestCLIEvaluateExplainDefaultAndEmptyRules(t *testing.T) {
	// 没有规则命中：展示全部规则，说明采用默认值。
	h := newHarness(t, explainCLIConfig, `{"plan":"free"}`)
	got := explainSuccess(t, h, "f")
	if got["reason"] != "default" || got["ruleId"] != nil || got["value"] != true {
		t.Fatalf("unexpected: %v", got)
	}
	if rules := rulesOf(t, got); len(rules) != 2 {
		t.Fatalf("all rules shown on default fallback: %v", rules)
	}
	exp := got["explanation"].(map[string]any)
	if !strings.Contains(strings.ToLower(exp["outcome"].(string)), "default") {
		t.Fatalf("outcome must mention default: %v", exp["outcome"])
	}

	// 空规则列表：默认结果 + 空解释。
	h2 := newHarness(t, explainCLIConfig, `{}`)
	got2 := explainSuccess(t, h2, "plain")
	if got2["reason"] != "default" || got2["ruleId"] != nil || got2["value"] != true {
		t.Fatalf("unexpected: %v", got2)
	}
	exp2 := got2["explanation"].(map[string]any)
	rules2, _ := exp2["rules"].([]any)
	if len(rules2) != 0 {
		t.Fatalf("empty rules must give empty explanation: %v", exp2["rules"])
	}
}

func TestCLIEvaluateExplainDisabled(t *testing.T) {
	// 即使上下文本会命中 r-only，关闭开关固定 false，规则解释为空。
	h := newHarness(t, explainCLIConfig, `{"plan":"pro"}`)
	got := explainSuccess(t, h, "off")
	if got["value"] != false || got["reason"] != "disabled" || got["ruleId"] != nil {
		t.Fatalf("unexpected: %v", got)
	}
	exp := got["explanation"].(map[string]any)
	rules, _ := exp["rules"].([]any)
	if len(rules) != 0 {
		t.Fatalf("disabled flag must have empty rule explanation: %v", rules)
	}
	if !strings.Contains(strings.ToLower(exp["outcome"].(string)), "disabled") {
		t.Fatalf("outcome must say disabled fixed false, not default/rule: %v", exp["outcome"])
	}
}

func TestCLIEvaluateExplainKeepsListEmptyAndDuplicates(t *testing.T) {
	cfg := `{"flags":[{"key":"g","enabled":true,"default":false,"rules":[
		{"id":"r","value":true,"conditions":[
			{"attribute":"tag","op":"in","value":["","a","a"," "]}]}]}]}`
	h := newHarness(t, cfg, `{"tag":""}`)
	var stdout, stderr bytes.Buffer
	if code := run(h.evalExplainArgs("g"), &stdout, &stderr); code != 0 {
		t.Fatalf("exit=%d stderr=%s", code, stderr.String())
	}
	// compareValue 必须逐字保留空字符串、重复成员、次序与空白。
	if !strings.Contains(stdout.String(), `"compareValue":["","a","a"," "]`) {
		t.Fatalf("compareValue must preserve empty/dup/order/whitespace: %s", stdout.String())
	}
}

func TestCLIEvaluateExplainNormalModeUnchanged(t *testing.T) {
	// 不带 --explain 仍是既有四字段对象，且不包含 explanation。
	h := newHarness(t, explainCLIConfig, `{"plan":"pro"}`)
	var stdout, stderr bytes.Buffer
	if code := run(h.evalArgs("plain"), &stdout, &stderr); code != 0 {
		t.Fatalf("exit=%d stderr=%s", code, stderr.String())
	}
	if want := `{"key":"plain","value":true,"reason":"default","ruleId":null}`; strings.TrimSpace(stdout.String()) != want {
		t.Fatalf("normal output changed: %q", stdout.String())
	}
	if strings.Contains(stdout.String(), "explanation") {
		t.Fatalf("normal mode must not include explanation: %q", stdout.String())
	}
}

func TestCLIEvaluateExplainArgumentRules(t *testing.T) {
	goodCtx := `{}`
	cases := []struct {
		name    string
		argv    func(h *harness) []string
		wantSub string
	}{
		{
			"unknown fourth argument",
			func(h *harness) []string {
				return []string{"evaluate", h.configPath, "plain", h.contextPath, "--verbose"}
			},
			"must be --explain",
		},
		{
			"fifth argument rejected",
			func(h *harness) []string {
				return []string{"evaluate", h.configPath, "plain", h.contextPath, "--explain", "x"}
			},
			"expected 3 arguments",
		},
		{
			"--explain in first position is a config path",
			func(h *harness) []string {
				return []string{"evaluate", "--explain", "plain", h.contextPath}
			},
			`cannot read config file "--explain"`,
		},
		{
			"--explain in second position is the flag key",
			func(h *harness) []string {
				return []string{"evaluate", h.configPath, "--explain", h.contextPath}
			},
			`flag key "--explain" not found`,
		},
		{
			"--explain in third position is the context path",
			func(h *harness) []string {
				return []string{"evaluate", h.configPath, "plain", "--explain"}
			},
			`cannot read context file "--explain"`,
		},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			h := newHarness(t, explainCLIConfig, goodCtx)
			var stdout, stderr bytes.Buffer
			code := run(tc.argv(h), &stdout, &stderr)
			if code == 0 {
				t.Fatalf("expected non-zero exit")
			}
			if stdout.Len() != 0 {
				t.Fatalf("stdout must be empty on argument error: %q", stdout.String())
			}
			if !strings.Contains(stderr.String(), tc.wantSub) {
				t.Fatalf("stderr=%q, want substring %q", stderr.String(), tc.wantSub)
			}
		})
	}
}

func TestCLIEvaluateExplainValidationStillWhole(t *testing.T) {
	// 带 --explain 也不能绕过整份配置/上下文校验：未选中/已关闭开关中的非法
	// 内容、上下文非字符串值都要非零退出、stdout 为空。
	cases := []struct {
		name    string
		config  string
		key     string
		context string
		wantSub string
	}{
		{
			"illegal disabled flag rule",
			`{"flags":[
				{"key":"good","enabled":true,"default":false,"rules":[]},
				{"key":"off","enabled":false,"default":true,"rules":[
					{"id":"r","value":true,"conditions":[]}]}]}`,
			"good", `{}`, "conditions",
		},
		{
			"context non-string",
			explainCLIConfig, "plain", `{"plan":5}`, "context.plan",
		},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			h := newHarness(t, tc.config, tc.context)
			var stdout, stderr bytes.Buffer
			if code := run(h.evalExplainArgs(tc.key), &stdout, &stderr); code == 0 {
				t.Fatalf("expected non-zero exit")
			}
			if stdout.Len() != 0 {
				t.Fatalf("stdout must be empty: %q", stdout.String())
			}
			if !strings.Contains(stderr.String(), tc.wantSub) {
				t.Fatalf("stderr=%q want %q", stderr.String(), tc.wantSub)
			}
		})
	}
}

func TestCLIEvaluateExplainHelp(t *testing.T) {
	var stdout, stderr bytes.Buffer
	if code := run([]string{"help"}, &stdout, &stderr); code != 0 {
		t.Fatalf("help exit=%d", code)
	}
	h := stdout.String()
	for _, frag := range []string{"[--explain]", "--explain", "explanation", "compareValue", "actualValue", "missing"} {
		if !strings.Contains(h, frag) {
			t.Errorf("help missing %q", frag)
		}
	}
}

