343	// TestInEscapedBackslashIsLiteralText 保护“转义只发生一次”：JSON 中的
344	// "\\u00E9" 解码为反斜杠加 u00E9 的普通文本，其后即使跟着 u 和十六进制数字也
345	// 不会再次解码；它只与相同的字面文本相等，与真正解码出的 é 互不命中。
346	func TestInEscapedBackslashIsLiteralText(t *testing.T) {
347		cfg := inCfg(`tier`, `["\\u00E9","\\uD83D\\uDE00"]`)
348		// 上下文给出相同的字面文本：命中。
349		if got := eval(t, cfg, "f", `{"tier":"\\u00E9"}`); got.Reason != EvalRule || !got.Value {
350			t.Fatalf("escaped-backslash text must equal the same literal text: %+v", got)
351		}
352		if got := eval(t, cfg, "f", `{"tier":"\\uD83D\\uDE00"}`); got.Reason != EvalRule || !got.Value {
353			t.Fatalf("surrogate-shaped literal text must equal itself: %+v", got)
354		}
355		// 真正解码出的字符（直接写出或用合法 Unicode 转义）与该字面文本不同。
356		for _, ctxRaw := range []string{`{"tier":"é"}`, `{"tier":"` + inEscEAcute + `"}`} {
357			if got := eval(t, cfg, "f", ctxRaw); got.Reason != EvalDefault {
358				t.Fatalf("decoded é must not equal backslash literal text (%s): %+v", ctxRaw, got)
359			}
360		}
361		if got := eval(t, cfg, "f", `{"tier":"😀"}`); got.Reason != EvalDefault {
362			t.Fatalf("decoded emoji must not equal surrogate-shaped literal text: %+v", got)
363		}
364		// 反向：列表只有解码后的 é 时，反斜杠字面文本不属于列表。
365		cfgDecoded := inCfg(`tier`, `["é"]`)
366		if got := eval(t, cfgDecoded, "f", `{"tier":"\\u00E9"}`); got.Reason != EvalDefault {
367			t.Fatalf("literal backslash text must not match a decoded-only list: %+v", got)
368		}
369		// 多一层转义（解码为两个反斜杠加 u00E9）又是另一个字符串。
370		if got := eval(t, cfg, "f", `{"tier":"\\\\u00E9"}`); got.Reason != EvalDefault {
371			t.Fatalf("double-escaped backslash is yet another literal string: %+v", got)
372		}
373	}
