1068				}
1069				if !strings.Contains(msg, tc.wantAttr) || !strings.Contains(msg, "value must be a string") {
1070					t.Fatalf("err=%q, want %s string-type error", msg, tc.wantAttr)
1071				}
1072				if tc.topLevelOnly && strings.Contains(msg, "inner") {
