1163			{"id":"r-neg","value":true,"conditions":[{"attribute":"plan","op":"eq","value":"-1e400"}]},
1164			{"id":"r-int","value":true,"conditions":[{"attribute":"plan","op":"eq","value":"` + hugeInt + `"}]}]}]}`
1165		for _, tc := range []struct {
