	// JSON 语法错误先于属性类型错误。
	if _, err := ParseContext([]byte(`{"a":1,`)); err == nil ||
		!strings.Contains(err.Error(), "invalid JSON") {
		t.Fatalf("syntax precedence: %v", err)
	}
}

